SET local check_function_bodies = off;

CREATE TABLE "public"."smoke_items" (
  "id"    bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "label" text   NOT NULL,
  CONSTRAINT "smoke_items_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."smoke_items"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."smoke_no_grant" (
  "id"    bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "label" text,
  CONSTRAINT "smoke_no_grant_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."smoke_no_grant"
  ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION public.smoke_ping()
  RETURNS text
  LANGUAGE sql
  AS $function$
  select 'pong'::text;
$function$;

REVOKE ALL ON FUNCTION "public"."smoke_ping"() FROM "service_role";

CREATE POLICY "smoke_items_select" ON "public"."smoke_items"
  FOR SELECT
  TO "anon", "authenticated"
  USING (true);

GRANT EXECUTE ON FUNCTION "public"."smoke_ping"() TO PUBLIC, "anon", "authenticated";

REVOKE ALL ON FUNCTION "public"."smoke_ping"() FROM "postgres";

GRANT EXECUTE ON FUNCTION "public"."smoke_ping"() TO "postgres";

REVOKE ALL ON SEQUENCE "public"."smoke_items_id_seq" FROM "anon";

GRANT UPDATE ON SEQUENCE "public"."smoke_items_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."smoke_items_id_seq" FROM "authenticated";

GRANT UPDATE ON SEQUENCE "public"."smoke_items_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."smoke_items_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."smoke_items_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."smoke_items_id_seq" FROM "service_role";

GRANT UPDATE ON SEQUENCE "public"."smoke_items_id_seq" TO "service_role";

REVOKE ALL ON SEQUENCE "public"."smoke_no_grant_id_seq" FROM "anon";

GRANT UPDATE ON SEQUENCE "public"."smoke_no_grant_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."smoke_no_grant_id_seq" FROM "authenticated";

GRANT UPDATE ON SEQUENCE "public"."smoke_no_grant_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."smoke_no_grant_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."smoke_no_grant_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."smoke_no_grant_id_seq" FROM "service_role";

GRANT UPDATE ON SEQUENCE "public"."smoke_no_grant_id_seq" TO "service_role";

REVOKE ALL ON TABLE "public"."smoke_items" FROM "anon";

GRANT MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE ON TABLE "public"."smoke_items" TO "anon";

REVOKE ALL ON TABLE "public"."smoke_items" FROM "authenticated";

GRANT MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE ON TABLE "public"."smoke_items" TO "authenticated";

REVOKE ALL ON TABLE "public"."smoke_items" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."smoke_items" TO "postgres";

REVOKE ALL ON TABLE "public"."smoke_items" FROM "service_role";

GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON TABLE "public"."smoke_items" TO "service_role";

REVOKE ALL ON TABLE "public"."smoke_no_grant" FROM "anon";

GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON TABLE "public"."smoke_no_grant" TO "anon";

REVOKE ALL ON TABLE "public"."smoke_no_grant" FROM "authenticated";

GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON TABLE "public"."smoke_no_grant" TO "authenticated";

REVOKE ALL ON TABLE "public"."smoke_no_grant" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."smoke_no_grant" TO "postgres";

REVOKE ALL ON TABLE "public"."smoke_no_grant" FROM "service_role";

GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON TABLE "public"."smoke_no_grant" TO "service_role";
